-- GenDB engine variant Q17-from_permutation: template q17.sql, kind from_permutation (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice) / 7.0 AS avg_yearly
FROM part, lineitem
WHERE
  p_partkey = l_partkey
  AND p_brand = $1
  AND p_container = $2
  AND l_quantity < (
    SELECT
      0.2 * AVG(l_quantity)
    FROM lineitem
    WHERE
      l_partkey = p_partkey
  )
